/* @component: more-text */
(function () {
  function initMoreText() {
    document.querySelectorAll('.more-text').forEach(function (container) {
      if (container.dataset.initialized === 'true') return;
      container.dataset.initialized = 'true';
      const btn = container.querySelector('.more-text-link');
      const span = container.querySelector('.more-text-span');
      const text = container.querySelector('.more-text-p');
      const svg = container.querySelector('.more-text-svg');
      if (!btn || !span || !text) return;
      let isAnimating = false;
      btn.addEventListener('click', function (e) {
        e.preventDefault();
        if (isAnimating) return;
        isAnimating = true;
        const isActive = text.classList.toggle('_is-active');
        if (svg) svg.style.transform = isActive ? 'rotate(180deg)' : 'rotate(0deg)';
        const collapsedHeight = '4.5em';
        const fullHeight = text.scrollHeight + 'px';
        const heightAnim = text.animate(
          [{ maxHeight: isActive ? collapsedHeight : fullHeight }, { maxHeight: isActive ? fullHeight : collapsedHeight }],
          { duration: 250, easing: 'ease', fill: 'forwards' }
        );
        span.textContent = isActive ? 'Скрыть' : 'Читать далее';
        heightAnim.addEventListener('finish', function () { isAnimating = false; });
      });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initMoreText);
  } else {
    initMoreText();
  }
  setTimeout(initMoreText, 300);
})();
/* @end: more-text */
